      "sources": [
        {"quote": "check 隔离环境 中的 connection-1707.csv", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "若 connection-1707.csv 存在差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
