      "sources": [
        {"quote": "若 connection-1707.csv 存在差异", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "否则无需生成 audit-471657.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
